function showMoreOptionBox(n,t){loadCollapse(n,$(n).next()[0],"/advertise/GetAdvertiseIndexDetails?advertiseId="+t)}function confirmHygieneProtocol(n,t){showConfirm("آیا رعایت پروتکل بهداشتی در این اقامتگاه مورد تایید است؟",function(){sendGetAjax("/accomodation/sethygieneprotocoladmin","id="+n+"&value=2",function(n){n.status==1&&($(t).remove(),successAlert())})})}function rejectHygieneProtocol(n,t){showConfirm("آیا از عدم تایید پروتکل های بهداشتی این اقامتگاه مطمئن هستید؟",function(){sendGetAjax("/accomodation/sethygieneprotocoladmin","id="+n+"&value=3",function(n){n.status==1&&($(t).remove(),successAlert())})})}function PublishAdvertise(n,t){showConfirm("آیا از انتشار این آگهی اطمینان دارید؟",function(){sendGetAjax("/accomodation/publish","id="+n,function(n){n.status==1&&($(t).remove(),successAlert())})})}function SuspenAdvertise(n,t){showConfirm("آیا از تعلیق این آگهی اطمینان دارید؟",function(){sendGetAjax("/accomodation/suspend","id="+n,function(n){n.status==1&&($(t).remove(),successAlert("آگهی مورد نظر تعلیق شد"))})})}function NotVerifyAdvertise(n,t){showConfirm("آیا از عدم تایید این آگهی اطمینان دارید؟",function(){sendGetAjax("/Advertise/NotVerify","id="+n,function(n){n.status==1&&($(t).remove(),successAlert("آگهی مورد نظر به تایید نشده ها پیوست"))})})}function showAddInfoDialog(n){showPopup("افزودن توضیحات به آگهی "+n+'<br/><input id="addInfoInput" type="text" style="width: 300px;" /><br /><button onclick="addInfo('+n+')" style="padding: 5px;margin:5px; width:100px; height: 30px;"><i class="fa fa-plus"><\/i> افزودن<\/button>')}function addInfo(n){var t=$("#addInfoInput").val();if(!t){errorAlert("لطفا توضیح مورد نظر را وارد کنید");return}sendGetAjax("/advertise/addsupporterinfotoadvertise","advertise_id="+n+"&text="+t,function(n){hidePopup();n.status==0?errorAlert("عملیات با خطا مواجه شد"):n.status==1&&successAlert("اطلاعات مورد نظر با موفقیت ثبت شد")})}function showInfo(n){loadPopup("/advertise/getadvertisesupporterinfo?advertise_id="+n)}$(".box-filter .submit-btn").click(function(){$('#more_filter_form [name="Id"]').val($('.box-filter .bar-filter [name="AdvertiseId"').val());$('#more_filter_form [name="UserId"]').val($('.box-filter .bar-filter [name="HostUserId"').val());$("#more_filter_form").submit()});$("#js-status-filter-select").change(function(){$(this).val()=="0"&&$("#js-sort-filter-select").val("modify")});